def _checkpoint_calls(path: Path) -> list[str]: tree = ast.parse(path.read_text(encoding='utf-8')); calls = [node for node in ast.walk(tree) if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id == 'checkpoint') and (len(node.args) == 2) and isinstance(node.args[1], ast.Constant)]; return [call.args[1].value for call in sorted(calls, key=lambda call: (call.lineno, call.col_offset))]
def _checkpoint_sequence(path: Path, function_name: str) -> list[str]:
    tree = ast.parse(path.read_text(encoding='utf-8')); functions = {node.name: node for node in tree.body if isinstance(node, ast.FunctionDef | ast.AsyncFunctionDef)}; marks: list[str] = []; expanded: set[str] = set()
    def visit(node: ast.AST) -> None:
        for child in ast.iter_child_nodes(node):
            if isinstance(child, ast.Call) and isinstance(child.func, ast.Name):
                name = child.func.id
                if name == 'checkpoint' and len(child.args) == 2 and isinstance(child.args[1], ast.Constant): marks.append(child.args[1].value); continue
                if name in functions and name not in expanded: [visit(argument) for argument in [*child.args, *child.keywords]]; expanded.add(name); visit(functions[name]); continue
            visit(child)
    expanded.add(function_name); visit(functions[function_name]); return marks
def _pytest_markers(path: Path, function_name: str) -> set[str]: tree = ast.parse(path.read_text(encoding='utf-8')); function = next((node for node in tree.body if isinstance(node, ast.FunctionDef | ast.AsyncFunctionDef) and node.name == function_name)); return {decorator.attr for decorator in function.decorator_list if isinstance(decorator, ast.Attribute) and isinstance(decorator.value, ast.Attribute) and (decorator.value.attr == 'mark')}
def _function_names(path: Path) -> set[str]: tree = ast.parse(path.read_text(encoding='utf-8')); return {node.name for node in ast.walk(tree) if isinstance(node, ast.FunctionDef | ast.AsyncFunctionDef)}
